import{_ as i,o as a,c as l,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Basic and Advanced Analysis of Ceph Volume Backend Driver in Cinder - John Haan","description":"","frontmatter":{"title":"Basic and Advanced Analysis of Ceph Volume Backend Driver in Cinder - John Haan","date":"2018-04-23T00:00:00.000Z","updated":"2018-04-24T00:00:00.000Z","tags":["Cinder","Ceph","Block Storage","Distributed Storage","OpenStack"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Basic_and_Advanced_Analysis_of_Ceph_Volume_Backend_Driver_in_Cinder_-_John_Haan.md","filePath":"posts/2018/Basic_and_Advanced_Analysis_of_Ceph_Volume_Backend_Driver_in_Cinder_-_John_Haan.md","lastUpdated":1780459816000}'),r={name:"posts/2018/Basic_and_Advanced_Analysis_of_Ceph_Volume_Backend_Driver_in_Cinder_-_John_Haan.md"};function d(o,e,t,s,_,c){return a(),l("div",null,[...e[0]||(e[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><p>Cinder块存储服务在Model公司的应用与实践</p><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><ul><li>Jan Man（Model公司存储团队负责人）</li><li>其他存储领域相关人员</li></ul><h4 id="会议内容" tabindex="-1">会议内容 <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容&quot;">​</a></h4><p><strong>1. Model公司背景介绍</strong></p><ul><li>Model公司是一家韩国游戏公司，专注于移动游戏开发和云服务。</li><li>自2016年起，Model公司采用基于Cinder的分布式存储环境，对游戏服务产生重大影响。</li></ul><p><strong>2. Cinder块存储服务架构</strong></p><ul><li>Model公司拥有8个Cinder集群，存储约PB级数据。</li><li>其中，3个集群用于玩家B/D及两个区域，4个集群用于Ingress和Block存储。</li><li>Cinder集群中，一个对象存储池作为主存储，容量利用率达到22%。</li></ul><p><strong>3. Cinder块存储服务特点</strong></p><ul><li>Cinder提供多种资源管理选项，如RBD（块设备）、Cinder卷等。</li><li>Cinder支持数据生命周期管理，包括快照、克隆等功能。</li><li>Cinder支持快照复制，用于数据备份和灾难恢复。</li></ul><p><strong>4. Cinder快照与克隆</strong></p><ul><li>Cinder支持快照和克隆功能，便于创建和管理数据副本。</li><li>快照基于原始数据的静态快照，克隆基于快照或原始数据的动态副本。</li><li>Cinder支持增量快照，减少数据传输量。</li></ul><p><strong>5. Cinder块存储服务的优化</strong></p><ul><li>Model公司使用不可变镜像功能，提高从镜像创建卷的性能。</li><li>使用图像缓存卷，减少数据传输量，提高性能。</li></ul><p><strong>6. Cinder块存储服务的应用</strong></p><ul><li>Model公司在Stack Overflow应用程序中使用了Cinder块存储服务。</li><li>Cinder块存储服务在Model公司的游戏服务和云服务中发挥着重要作用。</li></ul><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续优化Cinder块存储服务，提高性能和可靠性。</li><li>探索Cinder块存储服务的更多应用场景。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>Model公司将密切关注Cinder块存储服务的最新动态，不断优化和改进服务。</li><li>与社区合作，共同推动Cinder块存储技术的发展。</li></ul><h4 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h4><ul><li>Cinder块存储</li><li>RBD</li><li>快照</li><li>克隆</li><li>数据生命周期</li><li>可变镜像</li><li>图像缓存</li><li>Stack Overflow</li></ul>',24)])])}const p=i(r,[["render",d]]);export{u as __pageData,p as default};
